CREATE TABLE "MetaConnection" ("id" TEXT PRIMARY KEY,"ownerId" TEXT NOT NULL,"name" TEXT NOT NULL,"transport" TEXT NOT NULL CHECK ("transport" IN ('API','MCP')),"apiVersion" TEXT NOT NULL DEFAULT 'v23.0',"appId" TEXT,"encryptedToken" TEXT,"tokenMask" TEXT,"revision" INTEGER NOT NULL DEFAULT 1,"tools" JSONB NOT NULL DEFAULT '[]',"verifiedAt" TIMESTAMP(3),"disconnectedAt" TIMESTAMP(3),"lastError" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "MetaAdAccount" ("id" TEXT PRIMARY KEY,"connectionId" TEXT NOT NULL REFERENCES "MetaConnection"("id"),"name" TEXT NOT NULL,"businessId" TEXT,"businessName" TEXT,"currency" TEXT NOT NULL,"timezone" TEXT NOT NULL,"accountStatus" INTEGER,"enabled" BOOLEAN NOT NULL DEFAULT false,"metric" TEXT NOT NULL DEFAULT 'AUTO',"targetCost" DECIMAL(18,6),"minResults" INTEGER NOT NULL DEFAULT 10,"intervalMinutes" INTEGER NOT NULL DEFAULT 30,"historyFrom" TEXT,"syncedAt" TIMESTAMP(3),"nextSyncAt" TIMESTAMP(3),"syncState" JSONB NOT NULL DEFAULT '{}',"syncToken" TEXT,"syncLeaseAt" TIMESTAMP(3),"syncError" TEXT,"schedulerToken" TEXT,"schedulerRunId" TEXT);
CREATE INDEX "MetaAdAccount_enabled_nextSyncAt_idx" ON "MetaAdAccount"("enabled","nextSyncAt");
CREATE TABLE "MetaAccountGrant" ("id" TEXT PRIMARY KEY,"accountId" TEXT NOT NULL REFERENCES "MetaAdAccount"("id") ON DELETE CASCADE,"userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"canSync" BOOLEAN NOT NULL DEFAULT false);
CREATE UNIQUE INDEX "MetaAccountGrant_accountId_userId_key" ON "MetaAccountGrant"("accountId","userId");
CREATE INDEX "MetaAccountGrant_userId_idx" ON "MetaAccountGrant"("userId");
CREATE TABLE "MetaAdObject" ("id" TEXT PRIMARY KEY,"accountId" TEXT NOT NULL REFERENCES "MetaAdAccount"("id") ON DELETE CASCADE,"level" TEXT NOT NULL CHECK ("level" IN ('campaign','adset','ad')),"campaignId" TEXT,"adsetId" TEXT,"name" TEXT NOT NULL,"objective" TEXT,"optimizationGoal" TEXT,"status" TEXT,"effectiveStatus" TEXT,"createdTime" TIMESTAMP(3),"scheduledStart" TIMESTAMP(3),"thumbnailUrl" TEXT,"seenAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "MetaAdObject_accountId_level_campaignId_adsetId_idx" ON "MetaAdObject"("accountId","level","campaignId","adsetId");
CREATE TABLE "MetaAdDaily" ("id" TEXT PRIMARY KEY,"accountId" TEXT NOT NULL REFERENCES "MetaAdAccount"("id") ON DELETE CASCADE,"objectId" TEXT NOT NULL REFERENCES "MetaAdObject"("id") ON DELETE CASCADE,"day" TEXT NOT NULL,"scope" TEXT NOT NULL DEFAULT 'account-default',"spend" DECIMAL(18,6) NOT NULL,"impressions" DOUBLE PRECISION NOT NULL DEFAULT 0,"clicks" DOUBLE PRECISION NOT NULL DEFAULT 0,"actions" JSONB NOT NULL DEFAULT '{}',"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE UNIQUE INDEX "MetaAdDaily_objectId_day_scope_key" ON "MetaAdDaily"("objectId","day","scope");
CREATE INDEX "MetaAdDaily_accountId_day_idx" ON "MetaAdDaily"("accountId","day");
CREATE TABLE "MetaOAuthState" ("id" TEXT PRIMARY KEY,"connectionId" TEXT NOT NULL,"ownerId" TEXT NOT NULL,"sessionId" TEXT NOT NULL,"verifier" TEXT NOT NULL,"browserHash" TEXT NOT NULL,"tokenEndpoint" TEXT NOT NULL,"clientId" TEXT NOT NULL,"redirectUri" TEXT NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX "MetaOAuthState_expiresAt_idx" ON "MetaOAuthState"("expiresAt");

CREATE TABLE "MetaAccountSource" ("accountId" TEXT NOT NULL REFERENCES "MetaAdAccount"("id") ON DELETE CASCADE,"connectionId" TEXT NOT NULL REFERENCES "MetaConnection"("id") ON DELETE CASCADE,"revision" INTEGER NOT NULL,"verifiedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY("accountId","connectionId"));
